pub struct Quote {
    pub bid: u64,
    pub ask: u64,
    pub pnl_adj: i64,
}

pub fn build_quote(bid: u64, spread: u64, pnl_adj: i64) -> Quote {
    Quote { bid: bid, ask: bid.wrapping_add(spread), pnl_adj: pnl_adj }
}

pub fn quote_spread(q: Quote) -> u64 {
    q.ask.wrapping_sub(q.bid)
}

pub fn quote_net_mid(q: Quote) -> i64 {
    (q.bid.wrapping_add(q.ask.wrapping_sub(q.bid).checked_div(2u64).unwrap_or(0)) as i64).wrapping_add(q.pnl_adj)
}

pub fn scale_signed_pnl(pnl: i64) -> i64 {
    pnl.checked_div(10i64).unwrap_or(0)
}

